# ── Convenience lookups ────────────────────────────────────────────────────

ALL_MODALITY_IDS: list[str] = sorted(MODALITY_CATALOG.keys())


def get_categories() -> dict[str, list[str]]:
    """Return {category_slug: [modality_id, ...]} mapping."""
    cats: dict[str, list[str]] = {}
    for mod_id, entry in MODALITY_CATALOG.items():
        cats.setdefault(entry["category"], []).append(mod_id)
    return cats
